<COVER>        Integer oldValue = found.value;

<COVER>        while (found != null) {
            // 对应的上传索引节点
<COVER>            SkipListEntry upIndex = found.up;

            // 前驱和后继直接关联
<COVER>            SkipListEntry prev = found.left;
<COVER>            SkipListEntry succeed = found.right;
<COVER>            prev.right = succeed;
<COVER>            succeed.left = prev;

<COVER>            found = upIndex;
